        '5 \\[, \'አ“ጌሃ ፡ ሪቤ ፡ ሰሎሞን ፡ አግዚኣብሔር ፡ ነበበ ፡ ወይቤ ፣ ከመ ፡ ይሕድር ፡ ወስተ ፣ ዐውሎ። "ወአንሰ ፡ "ኀነጽኩ ፡ ቤተ ፡ ለስመ ፡ ዚኣሁ ፡ ቅዱስ ፡ ወድልው ፡ | ማኀዴሩ ፡ ለሣለም።',
