    (6, 19, "ወእመሰ ፡፣ አግ ፡ ሰማይ ፡ ወሰማዩ። ሰማያተ ፡ አኢ.ይክሉ ፡ ጸዊረ ፡ ስብሐቲከ ፡ ወ ምንትኑ ፡ ውእቱ ፡ ዝንቱ ፡ ቤት ፡ ዘአነ ፡ ሐነጽኩ።"),
