        7,
        19,
        'ወክከደግሙ ፡ ወረሳዕክሙመ ፡ ትአዘዝየ ፡ ወሕግየ ፡ ዘመጠከውኩክሙ ፡፣ ወሐርክመሙ፡ ፡ ወአምለክመሙ ፡ አማልክተ ፡ ነኪር ፡ ወሰገድክሙ ፡ ለ"መሙ ፡ ወአነሂ ፡ አፈልሰከሙ ፡ እምድር ፡ አንተ ፡ አወውረስክዎሙጮ ፡ ለአበቱክመሙ ፡ ወለገዝንቱ ፡ ቤት ፡ ዘቱዶዴስክያዎ።',
