        "ወአንበረ ንጉሥ ፡ በሰሎሞን ፡ ወርቀ ፡ ወብሩረ ፡ ውስተ ፡ አየሩሳሌም ፡ ከመ ፡ ኣብን ፡ ወዕፀወ ፡ ዘሣግበች ፡ ከመ ፡ ዕፀ ፡ በለስ ፡ ዘውስተ ፡ ሐቅል ፡ ብዙ። “ወምጽክአተ ፡ አፍራሲሊሁ ፡ ለሰሎሞን ፡ ንጉሥ ፡ አቻሦብሑሔረ ፡ ግብጽ ፡ ወእምኩሉ ፡ በሐውርት።",
