        "ሁ] ኮ 0/5. ወ. ~~ 2. እኘክስ] . ላA om. ~— Ib. ወትጤይቁኒ] ኮ ወትሔየቁኒ. ~— 6. ወይቤሎሪሁገ ፫ ወፅቤሎ. ~= 7. ቈረ] ኮ ር. ~= 0. ወስ መርክ] ኮ ዘስመርክሙ. ~= 6. ሠናይተ] ኮ ሠናያተ s፤ረ. ~~ 5. ስመላህቅት] ኮ ለመላህቅተ. — 0. ሪፅቀውመሙን ኾ ይውሪ sc. — 9. ምሣተገ] ኋ ምንተኑ. — 0. ታመክሩኒ] ኮ ታመካሪኒ፣ ኋላ ትመክሩኒ.። አቡከ ፡ በላዕሌነ።",
