    (13, 17, '"ወወዕክ ፡ ላዕሌሁ ፡ ዘሬ ፡ ንጉሥ ፣ ዘኢትዮጵያ ፡ በሰራዊት ፣ ጸኑዓን ተአል ፊተ ፡ አኣላፍ ፡ በ፤ ፡ ሰረገላት ፡ ወበጽሐ ፡ እስከ ፡ መሬስ።'),
