    (13, 19, '"ወጸርጎ ፣ አላ ፡ ኀበ ፡ አግዚ.ኣብሇሔር ፣ አምላኩ ፡ አንዘ ፡ ይብል ፡ እግዚኦ ፡ ኢሮሰአን ፡ በኀቤከ ፡ አድኅና ፡ በብዙኀ ፡ ወበኀሣጥ፥ፉ።'),
