    (17, 5, 'ሣ ፡ አግዚአብሔር ፣ በአደቁዋሁ ፡ ለንጉሥ። "ወይቤሉ ፡ ዮላፍጥ ፡ አልቦኑ ፡ ዝየ ፡ ነሽ. የ ፡ እግዚአብሔር ፡ ወዓዳ ፡ ጎሥሥ ፡ በኀቤሁ።'),
