    (18, 5, "ወይቤ ፡ ሚክያስ ፡ አመ ፡ ተመይ ጦስ ፡ ተመየጥከ ፡ በሰላም ፡ ኢተናገረ ፡ እግዚአብሔር ፡ በላዕሌየ ፡ ወስምዑ ፡ ዘንተ። ዙኵልክሙ፡፡ አሕዛብ።"),
