    (20, 15, '"ወእምድሣግረ ፡ ዝንቱ ፡ ዙሉ ፡ ቀተሉ ፡ እግዚኣብሔር ፡ በዝንቱ ፡ ደዊ። ከርሥ ፡ ዘል.ተረክኽበ ፡ ሎቱ ፡ ፈወስ።'),
