        16,
        "\"ወክነ ፡ አመ ፡ በጽሐ ሰኑይ ፡ መዋዕል ፡ አ ምዘ! ፡ ድዶወዩየ ፡ ወዕፅ ፡ አማዕሁ'ቱ ፡ ኣአምድሣሪረ ፡ ዴቁዊሁ ፡ ወሞተ ፡ በአከ.ት ፡ ዶዊ። ወል. ገብረ ፡ ሕዝብ ፡ ፀአተ ፡፣ ቀበረ ፡፣ ዚኣሁ ፡ በላዕሌሁ ፡ በከመ ፡ ቀበረ ፡ አበዊሁ።",
