    (21, 14, "አክተ ፡ ፻ ፡ ወለመላአክተ ፡ ኃይል ፡ ወይቤሎሙ ፡ አውዕአቁ ፡ አአ ፡ አምቤተ ፡ አግ ዘአብሔር ፡ ወዘተለዋ ፣ ኅግሬሃ ፡ ይሙት ፣ በመጥበሕተ።"),
