    (24, 14, "ወአለ ፣ ተርፋ ፡ ቃላ 23. አሣሞጸ ፡ ማእጊንትገ] ኋ 0). ~~ 23, ኢዮአስ] ኋ ኢየ አያስ.። ስራኤል ፡ ወይሆሁዳ።"),
