        '"ወኢ ይዷግም ፡ እንክ ፣ አፍልሶተ ፡ ኣግር ፣ አ ፣ ምእስራኤል ፣ እምዛቲ ፡ ምድር ፡ አንተ ፡ ወሀብክዎሙ ፡ ለአበዊክከሙ ፡ ወበሕቱሰ ፣ እመ ፡ ዐቀቡ ፡ ወገብሩ. ፡ ዙሎ ፡ ዘአዘዝክዎሙ ፡ በከመ ፡ ጽሑፍ ፡ ውስተ ፡ ሕግየ።',
