    (34, 17, "ኀበ ፡ ዙኵለሎሙ ፡ ደቂቀ ፡ ሕዝብ። ወእም’ ድግሪ ፡ አስተዳለዉ ፡ ወለክህናት ፡ ምስሌሆ መሙ ፡ ለአቅርቦ ፡ መሣብሕተ ፡ ወጽንሓሓተ ፡ እስከ ፡ ሌሊት።"),
